  expect(document.getElementById('minhas-inscricoes').hidden).toBe(true);
});

test('minhas erro ao carregar: mostra mensagem da API + tentar novamente', async () => {
  let tentativas = 0;
  const apiFake = criarApiFake((chamada) => {
