    }
    if (chamada.url.startsWith('http://api-fake.test/atividades/')) {
      return respostaFake(200, atv);
    }
    return respostaFake(404, { erro: 'NAO_ENCONTRADO', mensagem: 'x' });
  });
  const painel = montarPainel(apiFake);
